def parse_fasta(fasta_file, seq_len):
  seqs_1hot = []

  seq_dna = ''
  for line in open(fasta_file):
    if line[0] == '>':
      if len(seq_dna) > 0:
        # save full sequence
        seq_1hot = dna_1hot(seq_dna, seq_len)
        seqs_1hot.append(seq_1hot)

      # reset      
      seq_dna = ''

    else:
      # concat dna
      seq_dna += line.strip()

  if len(seq_dna) > 0:
    # save full sequence
    seq_1hot = dna_1hot(seq_dna, seq_len)
    seqs_1hot.append(seq_1hot)

  return np.array(seqs_1hot)


